function set_progress(p) {
    //console.log('set_progress %f', p);
    self.postMessage({
        type: 'set_progress',
        data: {
            p: p,
        }
    });
}

function add_out_image(imagedata) {
    self.postMessage({
        type: 'add_out_image',
        data: {
            imagedata: imagedata,
        }
    });
}

function texFromImageData(imageData) {
    var mat = new Module.JTex(imageData.height, imageData.width);
    mat.data.set(imageData.data);
    return mat;
};

self.onmessage = async function (event) {
    const { type, data } = event.data;
    if (type === 'init') {
        self.postMessage({ type: 'ready' });
    } else if (type === 'makeNumbers') {
        const { imgColor, imgPal, imgGrd, bVertPal } = data;
        try {
            var texCol = texFromImageData(imgColor);
            var texPal = texFromImageData(imgPal);
            var texGrd = texFromImageData(imgGrd);
            Module.make_numbers(texCol, texPal, texGrd, bVertPal);
        } catch (error) {
            self.postMessage({
                type: 'error',
                error: error
            });
        }
    }
};

